<?php
// Empty loopback database only; no real bookings, payment or provider calls.
define('WP_ADMIN',true);require '/var/www/html/wp-load.php';if(wp_parse_url(home_url(),PHP_URL_HOST)!=='127.0.0.1')exit(2);
use VPM\Booking\{DB,Core,Adapters,Products,Commerce,Journey,Workflows,Tenants};global $wpdb;$tables=$wpdb->get_col($wpdb->prepare('SHOW TABLES LIKE %s',$wpdb->prefix.'vpm_booking_%'));foreach($tables as $t)if($wpdb->get_var("SELECT COUNT(*) FROM $t"))throw new Exception('Nonempty fixtures refused');$options=[];foreach(['vpm_booking_products','vpm_booking_frontend_enabled','vpm_booking_guest_payment_enabled']as $k)$options[$k]=get_option($k,null);$checks=[];$users=[];
function scheck($v,$label){global $checks;if(!$v)throw new Exception($label);$checks[]=$label;}
try{wp_set_current_user(1);update_option('vpm_booking_products',[]);update_option('vpm_booking_frontend_enabled',true);update_option('vpm_booking_guest_payment_enabled',false);
$p=Core::partner(['airport'=>'MUC','name'=>'TEST München Außen','commission_bps'=>2000]);$id=(int)$p['id'];Adapters::configure($id,['mode'=>'manual']);Commerce::save($id,['services'=>['valet'=>['enabled'=>1,'fee_cents'=>1000]]]);$product=Products::save_template(['partner_id'=>(string)$id,'name_de'=>'TEST Außenstellplatz','name_en'=>'TEST Outdoor','parking_type'=>'outdoor']);Adapters::save_rate($id,['product_id'=>$product,'pricing'=>'24h','price_cents'=>'1000','capacity'=>'20','enabled'=>1]);
$d=['airport'=>'MUC','preferred_partner'=>'','parking_type'=>'outdoor','time_basis'=>'flight','service'=>'valet','departure'=>'2026-12-12T10:00','return'=>'2026-12-20T10:00','locale'=>'de'];
if(strtotime($d['departure'])<time()+DAY_IN_SECONDS){$d['departure']=gmdate('Y-m-d',time()+10*DAY_IN_SECONDS).'T10:00';$d['return']=gmdate('Y-m-d',time()+18*DAY_IN_SECONDS).'T10:00';}
scheck(count(Journey::offers($d)['offers'])===1,'Reported MUC outdoor/valet dates return the configured twenty-space offer');$alt=$d;$alt['parking_type']='underground';$result=Journey::offers($alt);scheck(count($result['alternatives'])===1,'Available outdoor alternative is returned for missing underground parking');$choice=$result['alternatives'][0];scheck(count(Journey::offers(array_merge($alt,$choice))['offers'])===1,'Following an available alternative returns a bookable offer');
update_option('vpm_booking_guest_payment_enabled',true);scheck(Journey::offers($d)['offers']===[],'Guest test checkout without partner payment mapping keeps its offer closed');scheck(Journey::offers($alt)['alternatives']===[],'An offer excluded by the payment gate must not be advertised as an available alternative');
$diagnostic=Workflows::search_check($id,array_merge($d,['product_id'=>$product]));$checksByName=array_column($diagnostic['checks'],null,'label');scheck(!$checksByName['Zahlungszuordnung für diesen Suchmodus']['ok'],'Private diagnostic identifies the missing Stripe mapping without exposing its value');scheck(!str_contains(json_encode($diagnostic),'stripe_account')&&!str_contains(json_encode($diagnostic),'customer_email'),'Diagnostic omits credentials and customer data');
update_option('vpm_booking_guest_payment_enabled',false);$roof=Products::save_template(['partner_id'=>(string)$id,'name_de'=>'TEST Garage ohne Höhe','name_en'=>'TEST Garage missing height','parking_type'=>'garage']);Adapters::save_rate($id,['product_id'=>$roof,'pricing'=>'24h','price_cents'=>'1000','capacity'=>'20','enabled'=>1]);$missing=$d;$missing['parking_type']='garage';$filtered=Journey::offers($missing);scheck($filtered['offers']===[]&&count($filtered['alternatives'])===1&&$filtered['alternatives'][0]['parking_type']==='outdoor','Filtering an invalid requested offer preserves genuinely bookable alternatives');scheck(Journey::offers($alt)['alternatives'][0]['parking_type']==='outdoor'&&count(Journey::offers($alt)['alternatives'])===1,'Missing-height garage is never advertised as an available alternative');
$hours=array_fill(1,7,'08:00-23:00');Commerce::save($id,['services'=>['valet'=>['enabled'=>1,'hours'=>$hours]]]);scheck(Journey::offers($d)['offers']===[],'Twenty spaces do not bypass valet hours at 07:00 flight-adjusted drop-off');$diagnostic=Workflows::search_check($id,array_merge($d,['product_id'=>$product]));$checksByName=array_column($diagnostic['checks'],null,'label');scheck(!$checksByName['Servicezeit bei Abgabe']['ok']&&$checksByName['Servicezeit bei Rückgabe']['ok'],'Diagnostic distinguishes closed drop-off from available collection time');scheck($checksByName['Freier Bestand im gesamten Parkzeitraum']['ok']&&str_contains($checksByName['Freier Bestand im gesamten Parkzeitraum']['detail'],'20 Gesamtplätze'),'Diagnostic distinguishes physical stock from service-hour exclusions');
scheck(str_contains($checksByName['Vorlauf und Aufenthaltsdauer zulässig']['detail'],'9 angefangene'),'Diagnostic explains the nine billable periods for the reported eight-day flight interval');Adapters::save_rate($id,['product_id'=>$product,'pricing'=>'24h','price_cents'=>'1000','capacity'=>'20']);$paused=Workflows::search_check($id,array_merge($d,['product_id'=>$product]));$byName=array_column($paused['checks'],null,'label');scheck(!$byName['Tarif zum Verkauf freigegeben']['ok']&&$byName['Freier Bestand im gesamten Parkzeitraum']['ok'],'Paused sale is diagnosed independently from twenty free physical spaces');
ob_start();Workflows::preview_ui($id);$ui=ob_get_clean();scheck(str_contains($ui,'value="shuttle"')&&str_contains($ui,'nicht aktiviert'),'Search check can also diagnose services that are not activated');
$other=Core::partner(['airport'=>'STR','name'=>'TEST Other tenant','commission_bps'=>2000]);$user=wp_insert_user(['user_login'=>'search_owner_'.bin2hex(random_bytes(4)),'user_pass'=>bin2hex(random_bytes(24)),'role'=>'subscriber']);$users[]=$user;Tenants::assign($id,$user,'owner');wp_set_current_user($user);try{Workflows::search_check((int)$other['id'],array_merge($d,['product_id'=>$product]));throw new Exception('Foreign diagnostic allowed');}catch(RuntimeException $e){scheck($e->getMessage()==='portal_forbidden','Search report is restricted to assigned partner');}wp_set_current_user(1);
file_put_contents('/tmp/vpm-booking-search-report.json',json_encode(['count'=>count($checks),'checks'=>$checks],JSON_PRETTY_PRINT));echo count($checks)." search regression checks passed\n";
}finally{wp_set_current_user(1);require_once ABSPATH.'wp-admin/includes/user.php';foreach($users as $user)wp_delete_user($user);foreach(array_reverse($tables)as $t)$wpdb->query("DELETE FROM $t");foreach($options as $k=>$v){if($v===null)delete_option($k);else update_option($k,$v);}}
